function translationsFromLanguagePacks(packs: Partial<Record<StudioLanguage, Record<string, string>>>): TranslationTable {
  const table: TranslationTable = {};
  for (const [language, entries] of Object.entries(packs) as Array<[StudioLanguage, Record<string, string>]>) {
    for (const [source, translated] of Object.entries(entries)) {
      table[source] = { ...(table[source] ?? {}), [language]: translated };
    }
  }
  return table;
}

